        <span className="text-text-secondary">{online === null ? "Checking platformΓÇª" : online ? "Platform online" : "Platform unreachable"}</span>
      </div>

      <div className="mt-6 flex gap-2 border-b border-border">
        {([
          ["discovery", "Innovation Radar"],
